COMMIT;

-- =========================================================================
-- VERIFICATION QUERY (Run this after COMMIT)
-- Confirms 1,500 active landmarks, 1,500 Urdu translations, and ZERO duplicates
-- =========================================================================
SELECT
  count(*) AS total_active_destinations,
  count(t.destination_id) AS total_urdu_translations,
  count(CASE WHEN t.destination_id IS NULL THEN 1 END) AS missing_urdu_count,
  count(d.image_url) AS authentic_photos_count,
  count(DISTINCT d.image_url) AS unique_photos_count,
  count(CASE WHEN d.image_url IS NULL THEN 1 END) AS native_gradient_icon_count
FROM public.destinations d
LEFT JOIN public.destination_translations t
  ON t.destination_id = d.id AND t.locale = 'ur'
WHERE d.active;
